import java.util.concurrent.*;

public final class BulkheadExecutorRouter {
    public enum Lane { FAST, SLOW, HEALTH }

    private final ThreadPoolExecutor fastPool = new ThreadPoolExecutor(
        48, 48, 0L, TimeUnit.MILLISECONDS,
        new ArrayBlockingQueue<>(64),
        namedFactory("fast-lane-"),
        new ThreadPoolExecutor.AbortPolicy()
    );

    private final ThreadPoolExecutor slowPool = new ThreadPoolExecutor(
        24, 24, 0L, TimeUnit.MILLISECONDS,
        new ArrayBlockingQueue<>(100),
        namedFactory("slow-lane-"),
        new ThreadPoolExecutor.AbortPolicy()
    );

    private final ThreadPoolExecutor healthPool = new ThreadPoolExecutor(
        2, 2, 0L, TimeUnit.MILLISECONDS,
        new ArrayBlockingQueue<>(16),
        namedFactory("health-lane-"),
        new ThreadPoolExecutor.AbortPolicy()
    );

    public <T> CompletableFuture<T> submit(Lane lane, long timeoutMs, Callable<T> task) {
        long deadlineNanos = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMs);
        ExecutorService target = switch (lane) {
            case FAST -> fastPool;
            case SLOW -> slowPool;
            case HEALTH -> healthPool;
        };
        CompletableFuture<T> future = new CompletableFuture<>();
        target.execute(() -> {
            if (System.nanoTime() > deadlineNanos) {
                future.cancel(false);
                return;
            }
            try {
                future.complete(task.call());
            } catch (Throwable t) {
                future.completeExceptionally(t);
            }
        });
        return future;
    }

    private static ThreadFactory namedFactory(String prefix) {
        AtomicInteger seq = new AtomicInteger(1);
        return r -> {
            Thread t = new Thread(r, prefix + seq.getAndIncrement());
            t.setDaemon(true);
            return t;
        };
    }
}

